// Author: MiYu. Stage-batch checks for live waygate configuration, entry and reciprocal destinations.
#include "session.h"
#include "setup.h"
#include <bit>
#include <cmath>
#include <iostream>

using namespace war3;
namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
float number(jass::Real value){return std::bit_cast<float>(value.bits());}
jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}
WorldPoint point(float x,float y){return {real(x),real(y)};}
std::vector<WorldPoint> openAreas(ScriptSession& session){auto& world=*session.world();auto bounds=world.bounds();std::vector<WorldPoint> result;for(float y=number(bounds.minY)+256;y<number(bounds.maxY)-256;y+=128)for(float x=number(bounds.minX)+256;x<number(bounds.maxX)-256;x+=128){bool free=true;for(int dy=-96;dy<=96 && free;dy+=32)for(int dx=-96;dx<=96;dx+=32)if(!world.pathPointFree(point(x+dx,y+dy),16,PathMovement::Ground)){free=false;break;}if(!free)continue;for(auto& [id,unit]:session.units())if(!unit->removing && !unit->hidden() && number(unit->life)>0 && std::hypot(number(unit->x)-x,number(unit->y)-y)<384+unit->collision){free=false;break;}if(!free)continue;if(!result.empty() && std::hypot(number(result[0].x)-x,number(result[0].y)-y)<1200)continue;result.push_back(point(x,y));if(result.size()==2)return result;}throw std::runtime_error("Two open areas unavailable");}
}
int wmain(int argc,wchar_t** argv){try{
    if(argc!=3)throw std::runtime_error("Usage: war3_waygate_tests <data-root> <map>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto areas=openAreas(session);auto owner=vm.handle("player",0x100000);auto code=[&](const char* id){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(id)));};auto create=[&](const char* id,WorldPoint p){auto unit=vm.invoke("CreateUnit",std::array{owner,code(id),vm.real(p.x),vm.real(p.y),vm.real(real(270))});vm.invoke("SetUnitPathing",std::array{unit,vm.boolean(false)});return unit;};auto first=create("nwgt",areas[0]),second=create("nwgt",areas[1]),unit=create("hfoo",point(number(areas[0].x)+100,number(areas[0].y)));auto before=session.units().at(unit.bits);session.advance(.03125);require(std::hypot(number(before->x)-number(areas[0].x),number(before->y)-number(areas[0].y))<200,"Unconfigured waygate transported unit");vm.invoke("WaygateSetDestination",std::array{first,vm.real(areas[1].x),vm.real(areas[1].y)});vm.invoke("WaygateSetDestination",std::array{second,vm.real(areas[0].x),vm.real(areas[0].y)});vm.invoke("WaygateActivate",std::array{first,vm.boolean(false)});require(!vm.invoke("WaygateIsActive",std::array{first}).bits,"Waygate deactivation lost");session.advance(.03125);require(std::hypot(number(before->x)-number(areas[0].x),number(before->y)-number(areas[0].y))<200,"Inactive waygate transported unit");vm.invoke("WaygateActivate",std::array{first,vm.boolean(true)});require(vm.invoke("WaygateGetDestinationX",std::array{first}).bits==areas[1].x.bits() && vm.invoke("WaygateGetDestinationY",std::array{first}).bits==areas[1].y.bits(),"Waygate destination was not stored");auto gateState=session.units().at(first.bits);gateState->waygate->retryAfter[unit.bits]=session.simulationTime()+.5;session.advance(.03125);require(std::hypot(number(before->x)-number(areas[0].x),number(before->y)-number(areas[0].y))<200,"Waygate ignored blocked retry delay");gateState->waygate->retryAfter[unit.bits]=session.simulationTime();session.advance(.03125);require(std::hypot(number(before->x)-number(areas[1].x),number(before->y)-number(areas[1].y))<320,"Waygate did not resume after retry delay");auto arrived=point(number(before->x),number(before->y));session.advance(.03125);require(std::hypot(number(before->x)-number(arrived.x),number(before->y)-number(arrived.y))<1,"Reciprocal gate immediately returned unit");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS waygate configuration, arrival and reciprocal entry\n";return 0;
}catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}}
